const raw = $json.body ?? $json;
const inputPayload = raw.payload && typeof raw.payload === 'object'
  ? raw.payload
  : (raw.body && raw.body.payload && typeof raw.body.payload === 'object' ? raw.body.payload : {});
const days = Math.max(1, Math.min(90, Number(inputPayload.days || raw.days || 30) || 30));
const requestId = String(raw.request_id || raw.requestId || `dsu-${Date.now()}`);
const dbPassword = $vars?.DS_AUDIT_DB_PASSWORD || '';

function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}
function sqlQuote(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "''")}'`;
}

const sql = [
  'SELECT request_id, trace_id, `operator`, source_system, country, action, target_type,',
  'project_code, workflow_code, workflow_name, instance_id, success, error_code, risk_level,',
  'duration_ms, operation_time',
  'FROM `ds_operation_audit_log`',
  `WHERE operation_time >= DATE_SUB(NOW(), INTERVAL ${days} DAY)`,
  'ORDER BY operation_time ASC',
].join(' ');

const errors = [];
if (!dbPassword) errors.push('missing n8n variable: DS_AUDIT_DB_PASSWORD');
if (!sql.trim()) errors.push('sql is required');

if (errors.length) {
  return [{ json: { valid: false, errors, requestId, days } }];
}

const meta = JSON.stringify({ requestId, days });
const remoteScript = [
  'set -euo pipefail',
  `printf '%s\\n' ${shellQuote(`__DSU_META__${meta}`)}`,
  `MYSQL_PWD=${shellQuote(dbPassword)} mysql --batch --raw --column-names ` +
    `--host=${shellQuote('10.20.47.19')} --port=3306 --user=${shellQuote('root')} ` +
    `--default-character-set=utf8mb4 ${shellQuote('warning_rule')} -e ${shellQuote(sql)}`,
].join('\n');

return [{ json: { valid: true, command: remoteScript, requestId, days } }];

const raw = $json;
const stdout = String(raw.stdout || raw.data || '');
const stderr = String(raw.stderr || raw.error?.message || '').trim();
const exitCode = raw.code ?? raw.exitCode ?? (raw.error ? 1 : 0);

function parseValue(value) {
  if (value === undefined || value === 'NULL') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(value)) {
    const n = Number(value);
    if (Number.isFinite(n)) return n;
  }
  return value;
}

const lines = stdout.split(/\r?\n/).filter((line) => line.length > 0);
let meta = {};
if (lines[0]?.startsWith('__DSU_META__')) {
  try { meta = JSON.parse(lines.shift().replace('__DSU_META__', '')); } catch {}
}

if (Number(exitCode) !== 0) {
  return [{ json: { success: false, requestId: meta.requestId || '', days: meta.days || 0, rows: [], rowCount: 0, error: { code: 'COMMAND_FAILED', message: stderr || 'ssh/mysql command failed', exit_code: exitCode } } }];
}

if (!lines.length) {
  return [{ json: { success: true, requestId: meta.requestId || '', days: meta.days || 0, rows: [], rowCount: 0 } }];
}

const headers = lines[0].split('\t');
const rows = lines.slice(1).map((line) => {
  const values = line.split('\t');
  return Object.fromEntries(headers.map((header, index) => [header, parseValue(values[index])]));
});

return [{ json: { success: true, requestId: meta.requestId || '', days: meta.days || 0, rows, rowCount: rows.length } }];

const raw = $json;
const errors = Array.isArray(raw.errors) ? raw.errors : ['invalid request'];
return [{
  json: {
    success: false,
    requestId: String(raw.requestId || raw.request_id || ''),
    days: Number(raw.days || 0),
    rows: [],
    rowCount: 0,
    error: { code: 'INVALID_REQUEST', message: errors.join('; ') || 'invalid request' },
  },
}];
